import { type Calendar, defaultCalendar } from './calendar';
import { MS_MINUTE, type OffsetTable, daysFromCivil, daysInMonth, instantsOfLocal, offsetAt } from './time';

export interface Bars {
  length: number;
  /** open instant, epoch ms UTC, a whole minute */
  t: Float64Array;
  open: Float64Array;
  high: Float64Array;
  low: Float64Array;
  close: Float64Array;
  /** null when the input had no volume */
  volume: Float64Array | null;
  /** a name for the data, shown in results ("your bars" by default) */
  label: string;
  /** set by the readers when the input was not in time order and had to be sorted */
  unsorted?: boolean;
}

export interface DataError {
  code: string;
  line: number | null;
  column: string | null;
  message: string;
}

export interface CapError {
  code: 'C_MAX_BARS' | 'C_MAX_SESSIONS' | 'C_CSV_TOO_LARGE' | 'C_QUERY_TOO_LONG' | 'C_TIMEOUT' | 'C_ABORTED';
  limit: number | null;
  message: string;
}

export interface Warning {
  code: string;
  message: string;
}

export interface CsvOptions {
  tz?: string;
  stamp?: 'open' | 'close';
  label?: string;
  calendar?: Calendar;
  maxBytes?: number;
  maxBars?: number;
}

export interface BarInput {
  t: number | string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume?: number;
}

export type BarsParseResult =
  | { ok: true; bars: Bars; warnings: Warning[] }
  | { ok: false; errors: (DataError | CapError)[] };

export const DEFAULT_LABEL = 'your bars';
export const DEFAULT_MAX_CSV_BYTES = 268435456;
export const DEFAULT_MAX_BARS = 5000000;
const MAX_ERRORS = 20;

export const W_UNSORTED: Warning = { code: 'W_UNSORTED', message: 'The bars were not in time order; they were sorted.' };

// ---- time zones ---------------------------------------------------------------

export type TzSpec =
  | { kind: 'zone'; name: string; table: OffsetTable }
  | { kind: 'fixed'; name: string; offset: number };

/** Resolve the `tz` option, or null when it is not one Setup Odds reads. */
export function resolveTz(value: string | undefined, cal: Calendar): TzSpec | null {
  const v = (value ?? 'America/New_York').trim();
  const low = v.toLowerCase();
  if (['america/new_york', 'et', 'ny', 'new_york'].includes(low)) return { kind: 'zone', name: 'America/New_York', table: cal.ny };
  if (['america/chicago', 'ct', 'chicago'].includes(low)) return { kind: 'zone', name: 'America/Chicago', table: cal.chicago };
  if (['utc', 'z', 'gmt'].includes(low)) return { kind: 'fixed', name: 'UTC', offset: 0 };
  const m = /^([+-])(\d{2}):(\d{2})$/.exec(v);
  if (m) {
    const h = +m[2], mi = +m[3];
    if (h > 23 || mi > 59) return null;
    return { kind: 'fixed', name: v, offset: (m[1] === '-' ? -1 : 1) * (h * 60 + mi) };
  }
  return null;
}

export function badTzError(value: string): DataError {
  return {
    code: 'D_BAD_TZ',
    line: null,
    column: null,
    message: `'${value}' is not a time zone Setup Odds reads. Use America/New_York, America/Chicago, UTC or an offset like -05:00.`,
  };
}

// ---- timestamps -----------------------------------------------------------------

const ISO_RE = /^(\d{4})-(\d{2})-(\d{2})[t ](\d{2}):(\d{2})(?::(\d{2})(?:\.(\d{1,3}))?)?(z|[+-]\d{2}:\d{2}|[+-]\d{4})?$/i;
const SLASH_RE = /^(\d{4})\/(\d{2})\/(\d{2}) (\d{2}):(\d{2})(?::(\d{2}))?$/;

type TsResult = { ok: true; t: number } | { ok: false; code: 'D_BAD_TIMESTAMP' | 'D_TS_NONEXISTENT' | 'D_OUT_OF_RANGE' };

/**
 * Convert one timestamp to an instant (before the `stamp` shift). `prev` is the instant of the
 * previous row resolved (null for the first row), used to resolve a repeated local hour.
 */
export function parseTimestamp(raw: string, tz: TzSpec, prev: number | null, range: OffsetTable): TsResult {
  const s = raw.trim();
  if (/^\d{9,10}$/.test(s)) return inRange(Number(s) * 1000, range);
  if (/^\d{12,13}$/.test(s)) return inRange(Number(s), range);
  let m = ISO_RE.exec(s);
  let zone: string | undefined;
  let y: number, mo: number, d: number, h: number, mi: number, se: number, ms: number;
  if (m) {
    y = +m[1]; mo = +m[2]; d = +m[3]; h = +m[4]; mi = +m[5];
    se = m[6] === undefined ? 0 : +m[6];
    ms = m[7] === undefined ? 0 : +(m[7] + '00').slice(0, 3);
    zone = m[8];
  } else {
    m = SLASH_RE.exec(s);
    if (!m) return { ok: false, code: 'D_BAD_TIMESTAMP' };
    y = +m[1]; mo = +m[2]; d = +m[3]; h = +m[4]; mi = +m[5];
    se = m[6] === undefined ? 0 : +m[6];
    ms = 0;
  }
  if (mo < 1 || mo > 12 || d < 1 || d > daysInMonth(y, mo) || h > 23 || mi > 59 || se > 59) return { ok: false, code: 'D_BAD_TIMESTAMP' };
  const local = daysFromCivil(y, mo, d) * 86400000 + h * 3600000 + mi * MS_MINUTE + se * 1000 + ms;
  if (zone !== undefined) {
    if (zone.toLowerCase() === 'z') return inRange(local, range);
    const zm = /^([+-])(\d{2}):?(\d{2})$/.exec(zone)!;
    const zh = +zm[2], zmi = +zm[3];
    if (zh > 23 || zmi > 59) return { ok: false, code: 'D_BAD_TIMESTAMP' };
    const off = (zm[1] === '-' ? -1 : 1) * (zh * 60 + zmi);
    return inRange(local - off * MS_MINUTE, range);
  }
  if (tz.kind === 'fixed') return inRange(local - tz.offset * MS_MINUTE, range);
  const cands = instantsOfLocal(tz.table, local);
  if (cands === null) return { ok: false, code: 'D_OUT_OF_RANGE' };
  if (cands.length === 0) return { ok: false, code: 'D_TS_NONEXISTENT' };
  if (cands.length === 1) return { ok: true, t: cands[0] };
  const [early, late] = cands;
  if (prev === null || early > prev) return { ok: true, t: early };
  return { ok: true, t: late };
}

function inRange(t: number, range: OffsetTable): TsResult {
  return offsetAt(range, t) === null ? { ok: false, code: 'D_OUT_OF_RANGE' } : { ok: true, t };
}

// ---- rows ------------------------------------------------------------------------

const NUM_RE = /^-?[0-9]+(\.[0-9]+)?([eE][-+]?[0-9]+)?$/;

interface RowSink {
  errors: DataError[];
  overflow: boolean;
  push(e: DataError): boolean;
}

function sink(): RowSink {
  return {
    errors: [],
    overflow: false,
    push(e) {
      if (this.errors.length >= MAX_ERRORS) {
        this.overflow = true;
        return false;
      }
      this.errors.push(e);
      return true;
    },
  };
}

interface GoodRow {
  t: number;
  o: number;
  h: number;
  l: number;
  c: number;
  v: number;
  line: number;
}

function ohlcRule(o: number, h: number, l: number, c: number): string | null {
  if (!(h >= l)) return 'high is below low';
  if (!(h >= o)) return 'high is below the open';
  if (!(h >= c)) return 'high is below the close';
  if (!(l <= o)) return 'low is above the open';
  if (!(l <= c)) return 'low is above the close';
  return null;
}

class RowReader {
  private seen = new Map<number, number>();
  private prevResolved: number | null = null;
  readonly rows: GoodRow[] = [];
  readonly out = sink();
  constructor(
    private tz: TzSpec,
    private stampClose: boolean,
    private range: OffsetTable,
    private hasVolume: boolean,
    private columnNames: { timestamp: string; open: string; high: string; low: string; close: string; volume: string | null },
  ) {}

  /** Returns false once the error limit is passed. */
  row(line: number, ts: string, cells: [string, string, string, string, string | null] | [number, number, number, number, number | null], tsIsNumber: number | null): boolean {
    const err = (code: string, column: string | null, message: string): boolean => this.out.push({ code, line, column, message });
    let t: number;
    if (tsIsNumber !== null) {
      t = tsIsNumber;
      if (offsetAt(this.range, t) === null) return err('D_OUT_OF_RANGE', this.columnNames.timestamp, `Line ${line}: ${ts} is outside the years the calendar covers.`);
    } else {
      const r = parseTimestamp(ts, this.tz, this.prevResolved, this.range);
      if (!r.ok) {
        if (r.code === 'D_BAD_TIMESTAMP') return err(r.code, this.columnNames.timestamp, `Line ${line}: '${ts}' is not a timestamp Setup Odds reads.`);
        if (r.code === 'D_OUT_OF_RANGE') return err(r.code, this.columnNames.timestamp, `Line ${line}: ${ts} is outside the years the calendar covers.`);
        return err(r.code, this.columnNames.timestamp, `Line ${line}: ${ts} does not exist in ${this.tz.name} (the clocks skip that hour).`);
      }
      t = r.t;
      this.prevResolved = t;
    }
    if (this.stampClose) t -= MS_MINUTE;
    if (!Number.isFinite(t) || t - Math.floor(t / MS_MINUTE) * MS_MINUTE !== 0)
      return err('D_TS_NOT_MINUTE', this.columnNames.timestamp, `Line ${line}: ${ts} is not on a whole minute. Setup Odds reads 1-minute bars.`);
    const names = [this.columnNames.open, this.columnNames.high, this.columnNames.low, this.columnNames.close, this.columnNames.volume ?? 'volume'];
    const vals: number[] = [];
    const last = this.hasVolume ? 5 : 4;
    for (let i = 0; i < last; i++) {
      const cell = cells[i];
      let x: number;
      if (typeof cell === 'number') {
        x = cell;
        if (!Number.isFinite(x)) return err('D_BAD_NUMBER', names[i], `Line ${line}: the ${names[i]} value '${String(cell)}' is not a number.`);
      } else {
        const sc = cell ?? '';
        if (!NUM_RE.test(sc)) return err('D_BAD_NUMBER', names[i], `Line ${line}: the ${names[i]} value '${sc}' is not a number.`);
        x = Number(sc);
        if (!Number.isFinite(x)) return err('D_BAD_NUMBER', names[i], `Line ${line}: the ${names[i]} value '${sc}' is not a number.`);
      }
      if (i === 4 && x < 0) return err('D_BAD_VOLUME', names[i], `Line ${line}: volume cannot be negative.`);
      vals.push(x);
    }
    const rule = ohlcRule(vals[0], vals[1], vals[2], vals[3]);
    if (rule) return err('D_OHLC', null, `Line ${line}: ${rule}.`);
    const other = this.seen.get(t);
    if (other !== undefined) return err('D_DUPLICATE', null, `Line ${line}: same minute as line ${other}.`);
    this.seen.set(t, line);
    this.rows.push({ t, o: vals[0], h: vals[1], l: vals[2], c: vals[3], v: this.hasVolume ? vals[4] : 0, line });
    return true;
  }

  finish(label: string, maxBars: number): BarsParseResult {
    if (this.out.errors.length) {
      const errors: (DataError | CapError)[] = [...this.out.errors];
      if (this.out.overflow) errors.push({ code: 'D_TOO_MANY_ERRORS', line: null, column: null, message: 'Stopped after 20 errors.' });
      return { ok: false, errors };
    }
    if (this.rows.length === 0) return { ok: false, errors: [{ code: 'D_EMPTY', line: null, column: null, message: 'The file has a header but no bars.' }] };
    if (this.rows.length > maxBars) return { ok: false, errors: [capMaxBars(this.rows.length, maxBars)] };
    let sorted = true;
    for (let i = 1; i < this.rows.length; i++) if (this.rows[i].t < this.rows[i - 1].t) { sorted = false; break; }
    const rows = sorted ? this.rows : this.rows.map((r, i) => ({ r, i })).sort((a, b) => a.r.t - b.r.t || a.i - b.i).map((x) => x.r);
    const n = rows.length;
    const bars: Bars = {
      length: n,
      t: new Float64Array(n),
      open: new Float64Array(n),
      high: new Float64Array(n),
      low: new Float64Array(n),
      close: new Float64Array(n),
      volume: this.hasVolume ? new Float64Array(n) : null,
      label,
    };
    for (let i = 0; i < n; i++) {
      const r = rows[i];
      bars.t[i] = r.t;
      bars.open[i] = r.o;
      bars.high[i] = r.h;
      bars.low[i] = r.l;
      bars.close[i] = r.c;
      if (bars.volume) bars.volume[i] = r.v;
    }
    if (!sorted) bars.unsorted = true;
    return { ok: true, bars, warnings: sorted ? [] : [W_UNSORTED] };
  }
}

export function capMaxBars(n: number, limit: number): CapError {
  return { code: 'C_MAX_BARS', limit, message: `The data has ${n} bars; this surface reads at most ${limit}.` };
}

function utf8Length(s: string): number {
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x80) n += 1;
    else if (c < 0x800) n += 2;
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
      n += 4;
      i++;
    } else n += 3;
  }
  return n;
}

// ---- CSV -------------------------------------------------------------------------

const ROLE_NAMES: Record<string, string[]> = {
  timestamp: ['timestamp', 'datetime', 'date_time', 'ts'],
  open: ['open', 'o'],
  high: ['high', 'h'],
  low: ['low', 'l'],
  close: ['close', 'c', 'last'],
  volume: ['volume', 'vol', 'v'],
};

const unquote = (s: string): string => {
  const t = s.trim();
  return t.length >= 2 && t[0] === '"' && t[t.length - 1] === '"' ? t.slice(1, -1) : t;
};

/** Read 1-minute bars from CSV text (SPEC § 6.2 to § 6.4). */
export function parseBarsCsv(text: string, options: CsvOptions = {}): BarsParseResult {
  const cal = options.calendar ?? defaultCalendar();
  const maxBytes = options.maxBytes ?? DEFAULT_MAX_CSV_BYTES;
  const bytes = utf8Length(text);
  if (bytes > maxBytes) return { ok: false, errors: [{ code: 'C_CSV_TOO_LARGE', limit: maxBytes, message: `The file is ${bytes} bytes; this surface reads at most ${maxBytes}.` }] };
  const tz = resolveTz(options.tz, cal);
  if (!tz) return { ok: false, errors: [badTzError(options.tz ?? '')] };
  let body = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  const lines = body.split('\n');
  body = '';
  let lineNo = 0;
  let header: string | null = null;
  let headerLine = 0;
  let i = 0;
  for (; i < lines.length; i++) {
    let l = lines[i];
    if (l.endsWith('\r')) l = l.slice(0, -1);
    lineNo = i + 1;
    const tr = l.trim();
    if (tr === '' || tr[0] === '#') continue;
    header = l;
    headerLine = lineNo;
    i++;
    break;
  }
  const noHeader: DataError = {
    code: 'D_NO_HEADER',
    line: header === null ? null : headerLine,
    column: null,
    message: 'The first line must be a header naming the columns (timestamp, open, high, low, close, volume).',
  };
  if (header === null) return { ok: false, errors: [noHeader] };
  const delim = [',', ';', '\t']
    .map((d) => ({ d, at: header!.indexOf(d) }))
    .filter((x) => x.at >= 0)
    .sort((a, b) => a.at - b.at)[0]?.d;
  if (!delim) return { ok: false, errors: [noHeader] };
  const names = header.split(delim).map((h) => unquote(h).toLowerCase());
  const col: Record<string, number> = {};
  const colName: Record<string, string> = {};
  const errs: DataError[] = [];
  const hasDate = names.includes('date');
  const hasTime = names.includes('time');
  const joinDateTime = hasDate && hasTime && !names.some((n) => ROLE_NAMES.timestamp.includes(n));
  names.forEach((nm, idx) => {
    let role: string | undefined;
    for (const [r, list] of Object.entries(ROLE_NAMES)) if (list.includes(nm)) role = r;
    if (!role && nm === 'time' && !joinDateTime && !(hasDate && hasTime)) role = 'timestamp';
    if (!role) return;
    if (role in col) {
      if (!errs.length) errs.push({ code: 'D_DUPLICATE_COLUMN', line: headerLine, column: nm, message: `The header names ${nm} twice.` });
      return;
    }
    col[role] = idx;
    colName[role] = nm;
  });
  if (errs.length) return { ok: false, errors: errs };
  let dateIdx = -1;
  let timeIdx = -1;
  if (!('timestamp' in col) && joinDateTime) {
    dateIdx = names.indexOf('date');
    timeIdx = names.indexOf('time');
    colName.timestamp = 'date';
  }
  for (const role of ['timestamp', 'open', 'high', 'low', 'close']) {
    if (role === 'timestamp' && dateIdx >= 0) continue;
    if (!(role in col)) return { ok: false, errors: [{ code: 'D_MISSING_COLUMN', line: headerLine, column: role, message: `The header has no ${role} column.` }] };
  }
  const hasVolume = 'volume' in col;
  const reader = new RowReader(tz, options.stamp === 'close', cal.ny, hasVolume, {
    timestamp: colName.timestamp,
    open: colName.open,
    high: colName.high,
    low: colName.low,
    close: colName.close,
    volume: hasVolume ? colName.volume : null,
  });
  const m = names.length;
  for (; i < lines.length; i++) {
    let l = lines[i];
    if (l.endsWith('\r')) l = l.slice(0, -1);
    const tr = l.trim();
    if (tr === '' || tr[0] === '#') continue;
    const line = i + 1;
    const cells = l.split(delim);
    if (cells.length < m) {
      if (!reader.out.push({ code: 'D_FIELD_COUNT', line, column: null, message: `Line ${line} has ${cells.length} values; the header has ${m} columns.` })) break;
      continue;
    }
    const cell = (k: number): string => unquote(cells[k]);
    const ts = dateIdx >= 0 ? cell(dateIdx) + ' ' + cell(timeIdx) : cell(col.timestamp);
    const ok = reader.row(line, ts, [cell(col.open), cell(col.high), cell(col.low), cell(col.close), hasVolume ? cell(col.volume) : null], null);
    if (!ok && reader.out.overflow) break;
  }
  return reader.finish(options.label ?? DEFAULT_LABEL, options.maxBars ?? DEFAULT_MAX_BARS);
}

/** Read bars from an array of objects (SPEC § 6.5). `line` in errors is the index plus 1. */
export function barsFromArray(rows: BarInput[], options: CsvOptions = {}): BarsParseResult {
  const cal = options.calendar ?? defaultCalendar();
  const tz = resolveTz(options.tz, cal);
  if (!tz) return { ok: false, errors: [badTzError(options.tz ?? '')] };
  const maxBars = options.maxBars ?? DEFAULT_MAX_BARS;
  if (rows.length > maxBars) return { ok: false, errors: [capMaxBars(rows.length, maxBars)] };
  const hasVolume = rows.length > 0 && rows[0].volume !== undefined;
  const reader = new RowReader(tz, options.stamp === 'close', cal.ny, hasVolume, {
    timestamp: 't',
    open: 'open',
    high: 'high',
    low: 'low',
    close: 'close',
    volume: hasVolume ? 'volume' : null,
  });
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const line = i + 1;
    const tsNum = typeof r.t === 'number' ? r.t : null;
    const ts = typeof r.t === 'number' ? String(r.t) : String(r.t);
    const vol = hasVolume ? (typeof r.volume === 'number' ? r.volume : NaN) : null;
    const ok = reader.row(line, ts, [num(r.open), num(r.high), num(r.low), num(r.close), vol], tsNum);
    if (!ok && reader.out.overflow) break;
  }
  return reader.finish(options.label ?? DEFAULT_LABEL, maxBars);
}

const num = (x: unknown): number => (typeof x === 'number' ? x : NaN);

/** Check a Bars value handed straight to a run: sort order, whole minutes, OHLC, the calendar's span. */
export function checkBars(bars: Bars, cal: Calendar): DataError[] {
  const errors: DataError[] = [];
  const push = (e: DataError): boolean => {
    if (errors.length >= MAX_ERRORS) {
      errors.push({ code: 'D_TOO_MANY_ERRORS', line: null, column: null, message: 'Stopped after 20 errors.' });
      return false;
    }
    errors.push(e);
    return true;
  };
  if (bars.length === 0) return [{ code: 'D_EMPTY', line: null, column: null, message: 'The file has a header but no bars.' }];
  for (let i = 0; i < bars.length; i++) {
    const line = i + 1;
    const t = bars.t[i];
    if (!Number.isFinite(t) || t - Math.floor(t / MS_MINUTE) * MS_MINUTE !== 0) {
      if (!push({ code: 'D_TS_NOT_MINUTE', line, column: 't', message: `Line ${line}: ${String(t)} is not on a whole minute. Setup Odds reads 1-minute bars.` })) break;
      continue;
    }
    if (offsetAt(cal.ny, t) === null) {
      if (!push({ code: 'D_OUT_OF_RANGE', line, column: 't', message: `Line ${line}: ${String(t)} is outside the years the calendar covers.` })) break;
      continue;
    }
    if (i > 0 && t === bars.t[i - 1]) {
      if (!push({ code: 'D_DUPLICATE', line, column: null, message: `Line ${line}: same minute as line ${i}.` })) break;
      continue;
    }
    if (i > 0 && t < bars.t[i - 1]) {
      if (!push({ code: 'D_UNSORTED', line, column: null, message: `Line ${line}: this bar opens before the bar above it. Bars must be sorted by time.` })) break;
      continue;
    }
    const vals = [bars.open[i], bars.high[i], bars.low[i], bars.close[i]];
    const names = ['open', 'high', 'low', 'close'];
    let bad = -1;
    for (let k = 0; k < 4; k++) if (!Number.isFinite(vals[k])) { bad = k; break; }
    if (bad >= 0) {
      if (!push({ code: 'D_BAD_NUMBER', line, column: names[bad], message: `Line ${line}: the ${names[bad]} value '${String(vals[bad])}' is not a number.` })) break;
      continue;
    }
    if (bars.volume) {
      const v = bars.volume[i];
      if (!Number.isFinite(v)) {
        if (!push({ code: 'D_BAD_NUMBER', line, column: 'volume', message: `Line ${line}: the volume value '${String(v)}' is not a number.` })) break;
        continue;
      }
      if (v < 0) {
        if (!push({ code: 'D_BAD_VOLUME', line, column: 'volume', message: `Line ${line}: volume cannot be negative.` })) break;
        continue;
      }
    }
    const rule = ohlcRule(vals[0], vals[1], vals[2], vals[3]);
    if (rule && !push({ code: 'D_OHLC', line, column: null, message: `Line ${line}: ${rule}.` })) break;
  }
  return errors;
}
